Given your stack (Node.js 18 + Express, Redis 7, DeepL API v2, translation microservice on port 4500) and your latency focus, here’s a proven pattern to make translation calls fast and resilient.

Key principles
- Avoid extra hops: Let DeepL auto-detect source language (don’t call your language-detection service on the hot path).
- Batch and dedupe: Translate arrays in one call; coalesce identical in-flight requests to prevent stampedes.
- Cache aggressively: Redis cache by hash of (source|target|text). Long TTL for deterministic outputs.
- Reuse connections: HTTP keep-alive and a single, long-lived API client.
- Handle rate limits: Retry with exponential backoff honoring Retry-After.
- Timeouts and fallbacks: Short timeouts, fallback to cached value on failure.
- Instrumentation: Track p50/p95, cache hit/miss, DeepL error/429s.

Minimal, fast Node.js implementation
- Supports single or batch requests
- Uses DeepL array translate in one call
- Redis caching with SHA-256 keys
- In-flight request dedupe
- Keep-alive HTTP agent + retries

```javascript
// npm i express redis axios undici crypto p-retry
const express = require('express');
const { createClient } = require('redis');
const axios = require('axios');
const { Agent } = require('undici');
const crypto = require('crypto');
const pRetry = require('p-retry');

const app = express();
app.use(express.json());

// DeepL REST config with keep-alive
const deepl = axios.create({
  baseURL: 'https://api.deepl.com/v2',
  timeout: 2500,
  httpAgent: new Agent({ connections: 10, pipelining: 1, keepAliveTimeout: 30_000 }),
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
});
const DEEPL_KEY = process.env.DEEPL_API_KEY;

// Redis v4 client (promises)
const redis = createClient({ url: process.env.REDIS_URL || 'redis://localhost:6379' });
redis.connect();

// Helpers
const hashKey = (sourceLang, targetLang, text) =>
  'tr:' + crypto.createHash('sha256').update(`${sourceLang || 'auto'}|${targetLang}|${text}`).digest('hex');

const inflight = new Map(); // single-flight dedupe

async function translateBatch({ texts, targetLang, sourceLang }) {
  // 1) Check cache
  const keys = texts.map(t => hashKey(sourceLang, targetLang, t));
  const cached = await redis.mGet(keys);
  const results = Array(texts.length).fill(null);
  const misses = [];
  const missIdx = [];

  cached.forEach((v, i) => {
    if (v) results[i] = v;
    else {
      misses.push(texts[i]);
      missIdx.push(i);
    }
  });

  if (misses.length === 0) return results;

  // 2) Coalesce in-flight misses by a request-group key
  const groupKey = crypto.createHash('sha256').update(JSON.stringify({ misses, targetLang, sourceLang })).digest('hex');
  if (inflight.has(groupKey)) {
    const fresh = await inflight.get(groupKey);
    fresh.forEach((txt, j) => { results[missIdx[j]] = txt; });
    return results;
  }

  const task = (async () => {
    // 3) Call DeepL once for all misses, auto-detect source if not provided
    const form = new URLSearchParams();
    form.append('auth_key', DEEPL_KEY);
    misses.forEach(t => form.append('text', t));
    form.append('target_lang', targetLang);
    if (sourceLang) form.append('source_lang', sourceLang);

    const doCall = async () => {
      try {
        const { data, headers } = await deepl.post('/translate', form);
        return data.translations.map(t => t.text);
      } catch (err) {
        const ra = err?.response?.headers?.['retry-after'];
        if (ra) {
          const wait = parseInt(ra, 10) * 1000 || 1000;
          await new Promise(r => setTimeout(r, wait));
        }
        throw err;
      }
    };

    const translated = await pRetry(doCall, {
      retries: 3,
      factor: 2,
      minTimeout: 300,
      maxTimeout: 1500,
      onFailedAttempt: e => {
        // optional: log e.attemptNumber, e.retriesLeft
      }
    });

    // 4) Write misses to cache (long TTL; adjust as needed)
    const pipeline = redis.multi();
    translated.forEach((txt, j) => pipeline.setEx(hashKey(sourceLang, targetLang, misses[j]), 24 * 3600, txt));
    await pipeline.exec();

    return translated;
  })();

  inflight.set(groupKey, task);
  try {
    const fresh = await task;
    fresh.forEach((txt, j) => { results[missIdx[j]] = txt; });
    return results;
  } finally {
    inflight.delete(groupKey);
  }
}

app.post('/translate', async (req, res) => {
  try {
    const { text, texts, targetLang, sourceLang } = req.body;
    if (!targetLang || (!text && !texts)) return res.status(400).json({ error: 'Provide text or texts[] and targetLang' });

    const items = texts || [text];
    const out = await translateBatch({ texts: items, targetLang, sourceLang }); // sourceLang optional (auto-detect)
    return res.json(texts ? { translations: out } : { translatedText: out[0] });
  } catch (e) {
    // Fallback: if error, try last-known cache for all items
    try {
      const items = req.body.texts || [req.body.text];
      const keys = items.map(t => hashKey(req.body.sourceLang, req.body.targetLang, t));
      const cached = await redis.mGet(keys);
      if (cached.some(Boolean)) {
        const filled = items.map((_, i) => cached[i] || null).filter(Boolean);
        if (req.body.texts) return res.status(206).json({ translations: filled, note: 'Partial cached fallback' });
        if (filled[0]) return res.status(206).json({ translatedText: filled[0], note: 'Cached fallback' });
      }
    } catch {}
    return res.status(502).json({ error: 'Translation failed' });
  }
});

app.listen(4500, () => console.log('Translation service on 4500'));
```

Why this is fast in practice
- One DeepL request for many texts: translate arrays in a single round trip.
- No language detection hop: rely on DeepL auto-detect unless you truly need to override.
- Redis-first: Most hits return in a few ms; misses are written back with long TTL.
- Single-flight: Prevents N identical misses hammering DeepL.
- Connection reuse: Keep-alive agent reduces TLS handshakes.
- Robustness: Short timeouts, exponential backoff, and Retry-After respect rate limits.

Operational tips
- Normalize cache keys carefully: Use exact text; avoid lossy transforms that can change meaning. Hash keys to keep them short.
- Tune TTLs by traffic pattern: Common UI strings (very long TTL), user free-form (a few hours to a day).
- Pre-warm cache: Pre-translate frequent UI copy and top phrases per language at deploy time.
- Co-locate: Run the service geographically close to your user base and to DeepL POPs to reduce RTT (you’re on AWS Fargate—choose regions accordingly).
- Metrics to watch: p50/p95 latency, cache hit rate, DeepL 429 rate, retries, timeouts.

